    var fgtsDeposit = fgtsBase * data.fgtsRate / 100;
    var penaltyRate = ['sem-justa-causa', 'rescisao-indireta', 'antecipada-empregador'].indexOf(data.reason) >= 0 ? 40 : data.reason === 'acordo' ? 20 : 0;
