      var totals = parsed.reduce(function (sum, item) { Object.keys(sum).forEach(function (key) { sum[key] += Number(item[key] || 0); }); return sum; }, { value: 0, icms: 0, ipi: 0, ii: 0, pis: 0, cofins: 0, iss: 0, ibs: 0, cbs: 0, selective: 0 });
