    var infNFeNode = byLocal('infNFe')[0];
    var chave = infNFeNode ? (infNFeNode.getAttribute('Id') || '').replace(/^NFe/, '') : '';
    var issueDate = pisCofinsFindText(doc, ['dhEmi', 'dEmi']);
